USE customer_behavior;
GO

-- Q1. Total revenue generated by male vs. female customers
SELECT
    gender,
    CAST(SUM(purchase_amount) AS DECIMAL(10, 2)) AS revenue
FROM dbo.customer
GROUP BY gender;


-- Q2. Customers who used a discount but spent at least the average purchase amount
SELECT
    customer_id,
    CAST(purchase_amount AS DECIMAL(10, 2)) AS purchase_amount
FROM dbo.customer
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (
      SELECT AVG(purchase_amount)
      FROM dbo.customer
  );


-- Q3. Top 5 products with the highest average review rating
SELECT TOP 5
    item_purchased,
    CAST(
        ROUND(AVG(CAST(review_rating AS DECIMAL(10, 2))), 2)
        AS DECIMAL(10, 2)
    ) AS [Average Product Rating]
FROM dbo.customer
GROUP BY item_purchased
ORDER BY AVG(CAST(review_rating AS DECIMAL(10, 2))) DESC;


-- Q4. Average purchase amount for Standard vs. Express Shipping
SELECT
    shipping_type,
    CAST(
        ROUND(AVG(CAST(purchase_amount AS DECIMAL(10, 2))), 2)
        AS DECIMAL(10, 2)
    ) AS avg_purchase_amount
FROM dbo.customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;


-- Q5. Average spend and total revenue for subscribers vs. non-subscribers
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customers,
    CAST(
        ROUND(AVG(CAST(purchase_amount AS DECIMAL(10, 2))), 2)
        AS DECIMAL(10, 2)
    ) AS avg_spend,
    CAST(SUM(purchase_amount) AS DECIMAL(10, 2)) AS total_revenue
FROM dbo.customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;


-- Q6. Top 5 products with the highest discount percentage
SELECT TOP 5
    item_purchased,
    CAST(
        ROUND(
            100.0 * SUM(
                CASE
                    WHEN discount_applied = 'Yes' THEN 1
                    ELSE 0
                END
            ) / NULLIF(COUNT(*), 0),
            2
        )
        AS DECIMAL(10, 2)
    ) AS discount_rate
FROM dbo.customer
GROUP BY item_purchased
ORDER BY discount_rate DESC, item_purchased;


-- Q7. Customer segmentation: New, Returning, and Loyal
WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases <= 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM dbo.customer
)
SELECT
    customer_segment,
    COUNT(*) AS [Number of Customers]
FROM customer_type
GROUP BY customer_segment
ORDER BY
    CASE customer_segment
        WHEN 'New' THEN 1
        WHEN 'Returning' THEN 2
        WHEN 'Loyal' THEN 3
    END;


-- Q8. Top 3 most purchased products within each category
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC, item_purchased
        ) AS item_rank
    FROM dbo.customer
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;


-- Q9. Repeat buyers (more than 5 previous purchases) by subscription status
SELECT
    subscription_status,
    COUNT(customer_id) AS repeat_buyers
FROM dbo.customer
WHERE previous_purchases > 5
GROUP BY subscription_status
ORDER BY subscription_status;


-- Q10. Revenue contribution of each age group
SELECT
    age_group,
    CAST(SUM(purchase_amount) AS DECIMAL(10, 2)) AS total_revenue
FROM dbo.customer
GROUP BY age_group
ORDER BY total_revenue DESC;